import unittest

from solution import TaskDrainer


class TaskDrainerTests(unittest.TestCase):
    def test_none_and_empty_sequences_drain_to_empty_tuple(self):
        self.assertEqual(TaskDrainer().drain(), ())
        self.assertEqual(TaskDrainer(None).drain(), ())
        self.assertEqual(TaskDrainer([]).drain(), ())
        self.assertEqual(TaskDrainer(()).drain(), ())

    def test_formats_in_order_and_is_repeatable(self):
        drainer = TaskDrainer([1, "two", None, True])
        expected = ("1", "two", "None", "True")
        self.assertEqual(drainer.drain(), expected)
        self.assertEqual(drainer.drain(), expected)

    def test_copies_caller_sequence(self):
        items = [1, 2]
        drainer = TaskDrainer(items)
        items[0] = 9
        items.append(3)
        self.assertEqual(drainer.drain(), ("1", "2"))

    def test_drain_dispatches_through_format_item_each_time(self):
        class RecordingDrainer(TaskDrainer):
            def __init__(self, items):
                super().__init__(items)
                self.calls = []

            def format_item(self, value):
                self.calls.append(value)
                return "[{}]".format(value)

        drainer = RecordingDrainer((3, 4))
        self.assertEqual(drainer.drain(), ("[3]", "[4]"))
        self.assertEqual(drainer.calls, [3, 4])
        self.assertEqual(drainer.drain(), ("[3]", "[4]"))
        self.assertEqual(drainer.calls, [3, 4, 3, 4])

    def test_format_item_uses_str(self):
        value = object()
        self.assertEqual(TaskDrainer().format_item(value), str(value))

    def test_rejects_other_constructor_inputs(self):
        for value in ("abc", {1, 2}, {"a": 1}, 3, True, iter([1, 2])):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    TaskDrainer(value)


if __name__ == "__main__":
    unittest.main()

